SET local check_function_bodies = off;

CREATE TABLE "public"."comment_mentions" (
  "comment_id" bigint                   NOT NULL,
  "user_id"    uuid                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "comment_mentions_pkey" PRIMARY KEY (comment_id, user_id)
);

ALTER TABLE "public"."comment_mentions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."comments" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "post_id"          bigint                   NOT NULL,
  "user_id"          uuid,
  "content"          text                     NOT NULL,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "parent_id"        bigint,
  "reply_to_user_id" uuid,
  CONSTRAINT "comments_content_check" CHECK (((char_length(content) >= 1) AND (char_length(content) <= 300))),
  CONSTRAINT "comments_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."comments"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."group_members" (
  "group_id"   bigint                   NOT NULL,
  "user_id"    uuid                     NOT NULL,
  "joined_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "sort_order" integer                  NOT NULL DEFAULT 0,
  CONSTRAINT "group_members_pkey" PRIMARY KEY (group_id, user_id)
);

ALTER TABLE "public"."group_members"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."groups" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"        text                     NOT NULL,
  "invite_code" text                     NOT NULL,
  "owner_id"    uuid                     NOT NULL,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "groups_invite_code_key" UNIQUE (invite_code),
  CONSTRAINT "groups_name_check" CHECK (((char_length(name) >= 1) AND (char_length(name) <= 30))),
  CONSTRAINT "groups_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."groups"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."likes" (
  "user_id"    uuid                     NOT NULL,
  "post_id"    bigint                   NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "likes_pkey" PRIMARY KEY (user_id, post_id)
);

ALTER TABLE "public"."likes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."notification_preferences" (
  "user_id"         uuid                     NOT NULL,
  "push_enabled"    boolean                  NOT NULL DEFAULT true,
  "post_enabled"    boolean                  NOT NULL DEFAULT true,
  "like_enabled"    boolean                  NOT NULL DEFAULT true,
  "comment_enabled" boolean                  NOT NULL DEFAULT true,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "notification_preferences_pkey" PRIMARY KEY (user_id)
);

ALTER TABLE "public"."notification_preferences"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."notifications" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"    uuid                     NOT NULL,
  "actor_id"   uuid                     NOT NULL,
  "type"       text                     NOT NULL,
  "post_id"    bigint                   NOT NULL,
  "comment_id" bigint,
  "is_read"    boolean                  NOT NULL DEFAULT false,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "notifications_not_self" CHECK ((user_id <> actor_id)),
  CONSTRAINT "notifications_pkey" PRIMARY KEY (id),
  CONSTRAINT "notifications_type_check" CHECK ((type = ANY (ARRAY['like'::text, 'comment'::text, 'post'::text, 'reply'::text, 'mention'::text])))
);

ALTER TABLE "public"."notifications"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."post_images" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "post_id"    bigint                   NOT NULL,
  "image_path" text                     NOT NULL,
  "sort_order" integer                  NOT NULL DEFAULT 0,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "post_images_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."post_images"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."posts" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"    uuid,
  "content"    text                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "image_path" text,
  "group_id"   bigint                   NOT NULL,
  CONSTRAINT "posts_content_check" CHECK (((char_length(content) >= 1) AND (char_length(content) <= 500))),
  CONSTRAINT "posts_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."posts"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."profiles" (
  "id"         uuid                     NOT NULL,
  "nickname"   text                     NOT NULL,
  "avatar_url" text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "profiles_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."profiles"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."push_subscriptions" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"    uuid                     NOT NULL,
  "endpoint"   text                     NOT NULL,
  "p256dh"     text                     NOT NULL,
  "auth"       text                     NOT NULL,
  "user_agent" text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "push_subscriptions_endpoint_unique" UNIQUE (endpoint),
  CONSTRAINT "push_subscriptions_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."push_subscriptions"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.can_access_avatar (
  target_path text
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
    owner_text text;
    owner_id uuid;
begin
    owner_text := split_part(target_path, '/', 1);

    begin
        owner_id := owner_text::uuid;
    exception
        when invalid_text_representation then
            return false;
    end;

    return
        owner_id = auth.uid()
        or exists (
            select 1
            from public.group_members me
            join public.group_members them
              on them.group_id = me.group_id
            where me.user_id = auth.uid()
              and them.user_id = owner_id
        );
end;
$function$;

CREATE OR REPLACE FUNCTION public.can_access_post (
  target_post_id bigint
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
    select exists (
        select 1
        from public.posts p
        join public.group_members gm
          on gm.group_id = p.group_id
        where p.id = target_post_id
          and gm.user_id = auth.uid()
    );
$function$;

CREATE OR REPLACE FUNCTION public.can_access_post_image (
  target_path text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
    select
        exists (
            select 1
            from public.posts p
            join public.group_members gm
              on gm.group_id = p.group_id
            where p.image_path = target_path
              and gm.user_id = auth.uid()
        )
        or
        exists (
            select 1
            from public.post_images pi
            join public.posts p
              on p.id = pi.post_id
            join public.group_members gm
              on gm.group_id = p.group_id
            where pi.image_path = target_path
              and gm.user_id = auth.uid()
        );
$function$;

CREATE OR REPLACE FUNCTION public.can_delete_my_account()
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
    select not exists (
        select 1
        from public.groups
        where owner_id = auth.uid()
    );
$function$;

CREATE OR REPLACE FUNCTION public.can_delete_post_image (
  target_path text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
    select
        -- 사진을 올린 본인
        split_part(target_path, '/', 1)
            = auth.uid()::text

        or

        -- 해당 사진이 속한 그룹의 방장
        exists (
            select 1
            from public.posts p
            join public.groups g
              on g.id = p.group_id
            where p.image_path = target_path
              and g.owner_id = auth.uid()
        );
$function$;

CREATE OR REPLACE FUNCTION public.create_group (
  group_name text
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
    new_group_id bigint;
    new_invite_code text;
    characters constant text :=
        'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    attempt integer := 0;
begin

    -- 로그인 확인
    if auth.uid() is null then
        raise exception '로그인이 필요합니다.';
    end if;

    -- 그룹 이름 확인
    group_name := trim(group_name);

    if group_name is null
       or char_length(group_name) < 1
       or char_length(group_name) > 30 then
        raise exception '그룹 이름은 1~30자로 입력해주세요.';
    end if;

    -- ========================================
    -- 중복되지 않는 초대코드 생성
    -- 최대 10번 재시도
    -- ========================================

    loop
        attempt := attempt + 1;

        new_invite_code := '';

        for i in 1..6 loop
            new_invite_code :=
                new_invite_code ||
                substr(
                    characters,
                    floor(
                        random() *
                        length(characters)
                    )::integer + 1,
                    1
                );
        end loop;

        exit when not exists (
            select 1
            from public.groups
            where invite_code =
                new_invite_code
        );

        if attempt >= 10 then
            raise exception
                '초대코드를 생성하지 못했습니다. 다시 시도해주세요.';
        end if;
    end loop;

    -- ========================================
    -- 그룹 생성
    -- ========================================

    insert into public.groups (
        name,
        invite_code,
        owner_id
    )
    values (
        group_name,
        new_invite_code,
        auth.uid()
    )
    returning id
    into new_group_id;

    -- ========================================
    -- 만든 사람을 자동으로 멤버 등록
    -- ========================================

    insert into public.group_members (
        group_id,
        user_id
    )
    values (
        new_group_id,
        auth.uid()
    );

    return new_group_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  insert into public.profiles (id, nickname)
  values (
    new.id,
    coalesce(
      new.raw_user_meta_data ->> 'nickname',
      split_part(new.email, '@', 1)
    )
  );

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.is_group_member (
  target_group_id bigint
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
    select exists (
        select 1
        from public.group_members
        where group_id = target_group_id
          and user_id = auth.uid()
    );
$function$;

CREATE OR REPLACE FUNCTION public.join_group_by_invite_code (
  code text
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
    found_group_id bigint;
begin

    if auth.uid() is null then
        raise exception '로그인이 필요합니다.';
    end if;

    if code is null or length(trim(code)) = 0 then
        raise exception '초대코드를 입력해주세요.';
    end if;

    select id
    into found_group_id
    from public.groups
    where invite_code = upper(trim(code));

    if found_group_id is null then
        raise exception '존재하지 않는 초대코드입니다.';
    end if;

    insert into public.group_members (
        group_id,
        user_id
    )
    values (
        found_group_id,
        auth.uid()
    )
    on conflict (
        group_id,
        user_id
    )
    do nothing;

    return found_group_id;

end;
$function$;

CREATE OR REPLACE FUNCTION public.register_push_subscription (
  p_endpoint   text,
  p_p256dh     text,
  p_auth       text,
  p_user_agent text DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
    v_user_id uuid;
begin
    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception '로그인이 필요합니다.';
    end if;

    if
        p_endpoint is null
        or length(trim(p_endpoint)) = 0
        or p_p256dh is null
        or length(trim(p_p256dh)) = 0
        or p_auth is null
        or length(trim(p_auth)) = 0
    then
        raise exception '잘못된 Push 구독 정보입니다.';
    end if;

    insert into public.push_subscriptions (
        user_id,
        endpoint,
        p256dh,
        auth,
        user_agent,
        updated_at
    )
    values (
        v_user_id,
        p_endpoint,
        p_p256dh,
        p_auth,
        p_user_agent,
        now()
    )
    on conflict (endpoint)
    do update set
        user_id = v_user_id,
        p256dh = excluded.p256dh,
        auth = excluded.auth,
        user_agent = excluded.user_agent,
        updated_at = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.shares_group_with (
  target_user_id uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
    select
        target_user_id = auth.uid()
        or exists (
            select 1
            from public.group_members me
            join public.group_members them
              on them.group_id = me.group_id
            where me.user_id = auth.uid()
              and them.user_id = target_user_id
        );
$function$;

CREATE OR REPLACE FUNCTION public.update_my_group_order (
  p_group_ids bigint[]
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
    v_user_id uuid := (select auth.uid());
    v_total integer;
begin
    if v_user_id is null then
        raise exception '로그인이 필요합니다.';
    end if;

    if p_group_ids is null
       or array_length(p_group_ids, 1) is null then
        raise exception '공간 목록이 비어 있습니다.';
    end if;

    -- 같은 사용자의 정렬 요청이 동시에 실행되지 않도록 잠금
    perform pg_advisory_xact_lock(
        hashtextextended(v_user_id::text, 0)
    );

    -- 사용자가 참여한 전체 공간 개수
    select count(*)
    into v_total
    from public.group_members
    where user_id = v_user_id;

    -- 전달된 공간 개수가 정확한지 확인
    if cardinality(p_group_ids) <> v_total then
        raise exception '내 공간 목록과 일치하지 않습니다.';
    end if;

    -- 중복 ID 또는 다른 사용자의 공간 ID 검사
    if exists (
        select 1
        from unnest(p_group_ids) as requested(group_id)
        left join public.group_members gm
            on gm.group_id = requested.group_id
           and gm.user_id = v_user_id
        group by requested.group_id
        having count(*) > 1
            or count(gm.group_id) = 0
    ) then
        raise exception '내 공간만 정렬할 수 있습니다.';
    end if;

    -- sort_order만 일괄 변경
    update public.group_members gm
    set sort_order = requested.new_order
    from (
        select
            group_id,
            (ordinality - 1)::integer as new_order
        from unnest(p_group_ids)
            with ordinality as ordered(group_id, ordinality)
    ) as requested
    where gm.user_id = v_user_id
      and gm.group_id = requested.group_id;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."update_my_group_order"(bigint[]) FROM PUBLIC, "anon";

