CREATE INDEX comment_mentions_user_id_idx ON public.comment_mentions USING btree (user_id);

CREATE INDEX comments_parent_id_idx ON public.comments USING btree (parent_id);

CREATE INDEX comments_reply_to_user_id_idx ON public.comments USING btree (reply_to_user_id);

CREATE INDEX group_members_user_sort_idx ON public.group_members USING btree (user_id, sort_order);

CREATE INDEX notifications_post_id_idx ON public.notifications USING btree (post_id);

CREATE INDEX notifications_user_created_at_idx ON public.notifications USING btree (user_id, created_at DESC);

CREATE INDEX push_subscriptions_user_id_idx ON public.push_subscriptions USING btree (user_id);

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();

CREATE POLICY "Group members can view comment mentions" ON "public"."comment_mentions"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.comments c
  WHERE ((c.id = comment_mentions.comment_id) AND public.can_access_post(c.post_id)))));

CREATE POLICY "Users can create comment mentions" ON "public"."comment_mentions"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((EXISTS ( SELECT 1
   FROM ((public.comments c
     JOIN public.posts p ON ((p.id = c.post_id)))
     JOIN public.group_members gm ON (((gm.group_id = p.group_id) AND (gm.user_id = auth.uid()))))
  WHERE (c.id = comment_mentions.comment_id))));

CREATE POLICY "group members can create own comments" ON "public"."comments"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((auth.uid() = user_id) AND public.can_access_post(post_id)));

CREATE POLICY "group members can read comments" ON "public"."comments"
  FOR SELECT
  TO "authenticated"
  USING (public.can_access_post(post_id));

CREATE POLICY "users can delete own group comments" ON "public"."comments"
  FOR DELETE
  TO "authenticated"
  USING (((auth.uid() = user_id) AND public.can_access_post(post_id)));

CREATE POLICY "group members can read members" ON "public"."group_members"
  FOR SELECT
  TO "authenticated"
  USING (public.is_group_member(group_id));

CREATE POLICY "users can leave own membership" ON "public"."group_members"
  FOR DELETE
  TO "authenticated"
  USING ((user_id = auth.uid()));

CREATE POLICY "group members can read groups" ON "public"."groups"
  FOR SELECT
  TO "authenticated"
  USING (((owner_id = auth.uid()) OR public.is_group_member(id)));

CREATE POLICY "owners can delete groups" ON "public"."groups"
  FOR DELETE
  TO "authenticated"
  USING ((owner_id = auth.uid()));

CREATE POLICY "owners can update groups" ON "public"."groups"
  FOR UPDATE
  TO "authenticated"
  USING ((owner_id = auth.uid()))
  WITH CHECK ((owner_id = auth.uid()));

CREATE POLICY "users can create groups" ON "public"."groups"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((owner_id = auth.uid()));

CREATE POLICY "group members can create own likes" ON "public"."likes"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((auth.uid() = user_id) AND public.can_access_post(post_id)));

CREATE POLICY "group members can read likes" ON "public"."likes"
  FOR SELECT
  TO "authenticated"
  USING (public.can_access_post(post_id));

CREATE POLICY "users can delete own group likes" ON "public"."likes"
  FOR DELETE
  TO "authenticated"
  USING (((auth.uid() = user_id) AND public.can_access_post(post_id)));

CREATE POLICY "Users can insert own notification preferences" ON "public"."notification_preferences"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can update own notification preferences" ON "public"."notification_preferences"
  FOR UPDATE
  TO "authenticated"
  USING ((auth.uid() = user_id))
  WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can view own notification preferences" ON "public"."notification_preferences"
  FOR SELECT
  TO "authenticated"
  USING ((auth.uid() = user_id));

CREATE POLICY "users can create notifications" ON "public"."notifications"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((actor_id = auth.uid()) AND (user_id <> auth.uid()) AND (EXISTS ( SELECT 1
   FROM public.posts
  WHERE ((posts.id = notifications.post_id) AND public.is_group_member(posts.group_id))))));

CREATE POLICY "users can delete own notifications" ON "public"."notifications"
  FOR DELETE
  TO "authenticated"
  USING ((user_id = auth.uid()));

CREATE POLICY "users can update own notifications" ON "public"."notifications"
  FOR UPDATE
  TO "authenticated"
  USING ((user_id = auth.uid()))
  WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "users can view own notifications" ON "public"."notifications"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = auth.uid()));

CREATE POLICY "group members can view post images" ON "public"."post_images"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.posts
  WHERE ((posts.id = post_images.post_id) AND public.is_group_member(posts.group_id)))));

CREATE POLICY "post owners can delete post images" ON "public"."post_images"
  FOR DELETE
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.posts
  WHERE ((posts.id = post_images.post_id) AND (posts.user_id = auth.uid()) AND public.is_group_member(posts.group_id)))));

CREATE POLICY "post owners can insert post images" ON "public"."post_images"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((EXISTS ( SELECT 1
   FROM public.posts
  WHERE ((posts.id = post_images.post_id) AND (posts.user_id = auth.uid()) AND public.is_group_member(posts.group_id)))));

CREATE POLICY "group members can create own posts" ON "public"."posts"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((auth.uid() = user_id) AND public.is_group_member(group_id)));

CREATE POLICY "group members can read posts" ON "public"."posts"
  FOR SELECT
  TO "authenticated"
  USING (public.is_group_member(group_id));

CREATE POLICY "users can delete own group posts" ON "public"."posts"
  FOR DELETE
  TO "authenticated"
  USING (((auth.uid() = user_id) AND public.is_group_member(group_id)));

CREATE POLICY "users can update own group posts" ON "public"."posts"
  FOR UPDATE
  TO "authenticated"
  USING (((auth.uid() = user_id) AND public.is_group_member(group_id)))
  WITH CHECK (((auth.uid() = user_id) AND public.is_group_member(group_id)));

CREATE POLICY "group members can read profiles" ON "public"."profiles"
  FOR SELECT
  TO "authenticated"
  USING (public.shares_group_with(id));

CREATE POLICY "users can insert own profile" ON "public"."profiles"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((auth.uid() = id));

CREATE POLICY "users can update own profile" ON "public"."profiles"
  FOR UPDATE
  TO "authenticated"
  USING ((auth.uid() = id))
  WITH CHECK ((auth.uid() = id));

CREATE POLICY "Users can delete own push subscriptions" ON "public"."push_subscriptions"
  FOR DELETE
  TO "authenticated"
  USING ((auth.uid() = user_id));

CREATE POLICY "Users can insert own push subscriptions" ON "public"."push_subscriptions"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can update own push subscriptions" ON "public"."push_subscriptions"
  FOR UPDATE
  TO "authenticated"
  USING ((auth.uid() = user_id))
  WITH CHECK ((auth.uid() = user_id));

CREATE POLICY "Users can view own push subscriptions" ON "public"."push_subscriptions"
  FOR SELECT
  TO "authenticated"
  USING ((auth.uid() = user_id));

CREATE POLICY "authenticated users can upload avatars" ON "storage"."objects"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid))));

CREATE POLICY "authenticated users can upload post images" ON "storage"."objects"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((bucket_id = 'post-images'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid))));

CREATE POLICY "group members can view avatars" ON "storage"."objects"
  FOR SELECT
  TO "authenticated"
  USING (((bucket_id = 'avatars'::text) AND public.can_access_avatar(name)));

CREATE POLICY "group members can view post images" ON "storage"."objects"
  FOR SELECT
  TO "authenticated"
  USING (((bucket_id = 'post-images'::text) AND public.can_access_post_image(name)));

CREATE POLICY "users and group owners can delete post images" ON "storage"."objects"
  FOR DELETE
  TO "authenticated"
  USING (((bucket_id = 'post-images'::text) AND public.can_delete_post_image(name)));

CREATE POLICY "users can delete own avatars" ON "storage"."objects"
  FOR DELETE
  TO "authenticated"
  USING (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid))));

CREATE POLICY "users can update own avatars" ON "storage"."objects"
  FOR UPDATE
  TO "authenticated"
  USING (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid))))
  WITH CHECK (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = ( SELECT (auth.uid())::text AS uid))));

